@contextlib.contextmanager
def temp_root():
    """把「库根」临时指向一个合成目录，**只在本进程内**改模块级变量。

    为什么要它：selftest 必须走真实的写盘路径（否则测的是另一个函数），
    但**绝对不能在真库上写**。做法是让 ROOT 在 selftest 期间整体指向 tempfile
    合成库——路径一字不改地跑，落点全在临时目录里。退出时无论成败都恢复。
    """
    old_root, old_cwd, old_env = ROOT, os.getcwd(), os.environ.get(QC_DIR_ENV)
    tmp = K.make_temp_dir(prefix="qc_fix_pdf_links_selftest_")
    try:
        globals()["ROOT"] = tmp
        os.chdir(tmp)
        # 缓存目录也指向合成库：否则"干跑写缓存"会落进真库 .qc/
        os.environ[QC_DIR_ENV] = os.path.join(tmp, ".qc")
        yield tmp
    finally:
        os.chdir(old_cwd)
        globals()["ROOT"] = old_root
        if old_env is None:
            os.environ.pop(QC_DIR_ENV, None)
        else:
            os.environ[QC_DIR_ENV] = old_env
        shutil.rmtree(tmp, ignore_errors=True)



def canon(s):
    """DOI 归一：只留字母数字，消除点/斜线/下划线写法差异。"""
    return re.sub(r'[^a-z0-9]', '', (s or '').lower())


def doi_from_filename(p):
    """从 DOI 派生文件名恢复 DOI：`10_1002_adfm_202400001__X.pdf` → `10.1002/adfm.202400001`。"""
    stem = os.path.splitext(os.path.basename(p))[0]
    parts = stem.split('__')[0].split('_')
    if len(parts) < 3 or parts[0] != '10':
        return None
    return "10.%s/%s" % (parts[1], ".".join(parts[2:]))


def doi_of_pdf(path, cache):
    """读 PDF 的 DOI（元数据优先，其次前两页正文）；带缓存。返回 '' 表示读不到。"""
    if path in cache:
        return cache[path]
    doi = ''
    try:
        import fitz
        d = fitz.open(path)
        md = d.metadata or {}
        blob = " ".join(str(md.get(k, '')) for k in ('subject', 'keywords', 'title'))
        hit = DOI_RE.findall(blob)
        if not hit:
            txt = " ".join(d[i].get_text() for i in range(min(2, d.page_count)))
            hit = DOI_RE.findall(txt)
        d.close()
        if hit:
            doi = hit[0].rstrip('.,;)')
    except Exception:
        doi = ''
    cache[path] = doi
    return doi


def cache_path():
    """DOI 缓存落点。

    🔴 为什么显式看 `MATSCI_QC_DIR`：缓存的**写出**只允许发生在 apply 路径上
    （见 `build_map(save_cache=…)`）。selftest 需要把这条路径整体指到合成目录，
    否则"证明干跑无副作用"这件事就没法在真库上验证。
    """
    from kb_lib import qc_work_dir
    env = os.environ.get(QC_DIR_ENV)
    d = env if env else qc_work_dir(create=True)
    return os.path.join(d, 'pdf_doi_cache_fix.json')


class Cache:
    """DOI 缓存（落 QC 工作目录，避免每次重扫 300 个 PDF）。"""

    def __init__(self, path):
        self.path = path
        self.d = {}
        if os.path.exists(path):
            try:
                self.d = json.load(open(path, encoding='utf-8'))
            except Exception:
                self.d = {}

    def get(self, k):
        return self.d.get(k, None)

    def __contains__(self, k):
        return k in self.d

    def __setitem__(self, k, v):
        self.d[k] = v

    def save(self):
        os.makedirs(os.path.dirname(self.path), exist_ok=True)
        json.dump(self.d, open(self.path, 'w', encoding='utf-8'),
                  ensure_ascii=False, indent=1)


def build_map(verbose=True, save_cache=False):
    """返回 (mapping, broken_total, unresolved, cache)。

    🔴 `save_cache` 默认为 **False**：本函数**原先无条件** `cache.save()`，
    于是每一次**干跑**都会重写 `.qc/pdf_doi_cache_fix.json`（实测 49 KB）。
    干跑的定义是"不改变仓库状态"，不是"不改变 wiki 页面"——
    「默认干跑」这条纪律的本意包含"不落任何运行产物"。
    

    mapping: {断链目标: (磁盘实际路径, 配对方法)}
    配对按**可信度递减的三级**，每级都必须唯一命中，否则不配对（宁缺勿滥）：

      ① `doi`   —— 断链名是 DOI 派生名（`10_..._...__标题.pdf`）时，取其 DOI，
                   与磁盘 PDF 元数据/前两页正文里的 DOI 比对。**最强证据**：
                   同一 DOI 即同一篇文献。
      ② `title-prefix` —— 断链名去掉 DOI 前缀后，是磁盘文件名**归一化标题的
                   严格前缀**（DOI 派生名常把标题截到 ~80 字符）。要求磁盘上
                   只有 1 个这样命名的文件（唯一性）。
      ③ `card-title` —— 断链名是短别名式名（如 `2026-模型B…-npjCM.pdf`），
                   此时用该 source 卡 frontmatter 的 `aliases`/`summary` 里的
                   **英文标题**，与磁盘文件名标题做归一化后**唯一**匹配。
                   仅当前两级都失败时使用。
    """
    # 1. 收断链
    want = {}
    total = 0
    for f in sorted(glob.glob('wiki/sources/*.md')):
        t = read_text(f)
        fm_text, _ = split_frontmatter(t)
        for m in LINK_RE.finditer(fm_text or ''):
            tgt = m.group(1)
            if os.path.exists(tgt):
                continue
            total += 1
            want.setdefault(tgt, f)

    cache = Cache(cache_path())
    pdfs = sorted(glob.glob('raw/**/*.pdf', recursive=True))
    if verbose:
        print(f"扫描 {len(pdfs)} 个 PDF 的 DOI ...")
    for p in pdfs:
        if p not in cache:
            doi_of_pdf(p, cache.d)
    if save_cache:
        cache.save()         # 只有 apply 路径才落盘（干跑：缓存只留在内存里）

    def norm(s):
        return re.sub(r'[^a-z0-9]+', ' ', (s or '').lower()).strip()

    def disk_title(fn):
        b = os.path.splitext(os.path.basename(fn))[0]
        mm = re.match(r'^(.*?)\s+-\s+[^-]+-\s+(?:19|20)\d\d\s*$', b)
        return mm.group(1) if mm else b

    mapping = {}
    # ---- ① DOI ----
    doi_index = {}
    for p in pdfs:
        doi = cache.get(p) or ''
        if doi:
            doi_index.setdefault(canon(doi), []).append(p)
    for tgt in want:
        d = doi_from_filename(tgt)
        if d and len(doi_index.get(canon(d), [])) == 1:
            mapping[tgt] = (doi_index[canon(d)][0], 'doi')

    # ---- ② 标题前缀（唯一）----
    for tgt in want:
        if tgt in mapping:
            continue
        b = os.path.basename(tgt)
        if '__' not in b:
            continue
        tp = norm(b.split('__', 1)[1][:-4])
        if len(tp) < 20:
            continue
        cands = [p for p in pdfs if norm(disk_title(p)).startswith(tp)]
        if len(cands) == 1:
            mapping[tgt] = (cands[0], 'title-prefix')

    # ---- ③ 卡片英文标题（唯一）----
    for tgt, srcpage in want.items():
        if tgt in mapping:
            continue
        fm_text, _ = split_frontmatter(read_text(srcpage))
        if not fm_text:
            continue
        try:
            import yaml
            d = yaml.safe_load(fm_text) or {}
        except Exception:
            continue
        # 候选文本：aliases 里像英文标题的 + title 字段
        cands_txt = []
        for a in (d.get('aliases') or []):
            a = str(a)
            if len(a) >= 25 and len(re.findall(r'[A-Za-z]', a)) / max(1, len(a)) > 0.7:
                cands_txt.append(a)
        if d.get('title'):
            cands_txt.append(str(d['title']))
        # 每个候选各自找「归一化标题前缀」唯一命中的磁盘文件；
        # 多个候选指向**同一个**文件也算一致（同一篇论文常有多个别名写法）。
        votes = {}
        for ct in cands_txt:
            nct = norm(ct)
            if len(nct) < 20:
                continue
            m2 = [p for p in pdfs if norm(disk_title(p)).startswith(nct)]
            if len(m2) == 1:
                votes[m2[0]] = votes.get(m2[0], 0) + 1
        if len(votes) == 1:
            mapping[tgt] = (next(iter(votes)), 'card-title')

    unresolved = sorted(t for t in want if t not in mapping)
    return mapping, total, unresolved, cache


def selftest():
    ok = True

    # 🔴 守卫：进入时对真实落点拍快照，退出前比对——证明自检没碰真实库
    guard = _guard_state(wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),))

    # DOI 反算链条：DOI 派生名 → DOI → canon
    d = doi_from_filename('raw/pdf/10_1002_adfm_202400001__X.pdf')
    want = '10.1002/adfm.202400001'
    print(f"  [{'ok' if d == want else 'FAIL'}] DOI 派生名反算 -> {d}")
    ok = ok and d == want
    # 反例：标题名不得造出 DOI（否则会拿标题去瞎匹配）
    d = doi_from_filename('raw/pdf/AFLOW - An automatic framework - 2012.pdf')
    print(f"  [{'ok' if d is None else 'FAIL'}] 反例 标题名 -> None")
    ok = ok and d is None
    # canon 跨写法等价
    same = canon('10.1002/adfm.202400001') == canon('10_1002_adfm_202400001')
    print(f"  [{'ok' if same else 'FAIL'}] canon 跨写法等价")
    ok = ok and same
    # 链接正则：必须保留别名（本库 4 号事故同型：带别名的链接一条都匹配不到）
    s = '- "[[raw/pdf/10_x_y__T.pdf|别名 A]]"'
    m = LINK_RE.search(s)
    got = (m.group(1), m.group(2)) if m else None
    good = got == ('raw/pdf/10_x_y__T.pdf', '|别名 A')
    print(f"  [{'ok' if good else 'FAIL'}] 链接正则保留别名 -> {got}")
    ok = ok and good
    # 反例：非 raw/pdf 链接不得命中
    m = LINK_RE.search('- "[[concepts/固态电解质]]"')
    print(f"  [{'ok' if m is None else 'FAIL'}] 反例 非 raw/pdf 链接不命中")
    ok = ok and m is None

    # ---- 夹具（只对合成库，绝不碰真库）----
    try:
        with temp_root() as tmp:
            sd = os.path.join(tmp, "wiki", "sources")
            pd = os.path.join(tmp, "raw", "pdf")
            os.makedirs(sd, exist_ok=True)
            os.makedirs(pd, exist_ok=True)
            # 磁盘上的"改名后"PDF（占位文件即可：合成页直接引用它，无需解析 DOI）
            real_pdf = os.path.join(pd, "真实标题 - npjCM - 2026.pdf")
            with open(real_pdf, "wb") as fh:
                fh.write(b"%PDF-1.4 placeholder")
            p_src = os.path.join(sd, "S-断链.md")
            with open(p_src, "w", encoding="utf-8", newline="\n") as fh:
                fh.write('---\ntype: source\nsources:\n'
                         '  - "[[raw/pdf/10_1002_adfm_202400001__T.pdf]]"\n'
                         "---\n\n# 来源页\n正文\n")

            # 夹具 1（正例）：LINK_RE 在同一条里既取目标又保留别名
            m2 = LINK_RE.search('  - "[[raw/pdf/a_b_c__T.pdf|别名]]"')
            c1 = bool(m2) and m2.group(1) == 'raw/pdf/a_b_c__T.pdf' and m2.group(2) == '|别名'
            print(f"  [{'ok' if c1 else 'FAIL'}] 夹具 正例 直接构造的映射可安全改写")
            ok = ok and c1

            # 🔴 夹具 2：干跑分支**零写盘副作用**（缓存不得落盘）
            cp = cache_path()
            _map, _tot, _unres, _cache = build_map(verbose=False, save_cache=False)
            c2 = not os.path.exists(cp)
            print(f"  [{'ok' if c2 else 'FAIL'}] 🔴 夹具 干跑无副作用：DOI 缓存未落盘 -> {cp}")
            ok = ok and c2

            # 夹具 3（🔴 frontmatter 不丢）：走真实写盘路径：备份 → 写 → 写后复算
            new_fm = 'type: source\nsources:\n  - "[[raw/pdf/真实标题 - npjCM - 2026.pdf]]"'
            new_text = join_frontmatter(new_fm, "# 来源页\n正文\n")
            chk, _ = split_frontmatter(new_text)
            saved = backup_files([p_src])
            write_keep_eol(p_src, new_text)
            fm, body = split_frontmatter(read_text(p_src))
            c3 = (bool(chk.strip()) and len(saved) == 1
                  and "真实标题" in fm and body.lstrip().startswith("# 来源页"))
            print(f"  [{'ok' if c3 else 'FAIL'}] 🔴 夹具 frontmatter 不丢：写后回链已改且 "
                  f"frontmatter 可解析（备份 {len(saved)}）")
            ok = ok and c3

            # 反例：写后复算必须抓出"写了但 frontmatter 读不出"的页
            p_broken = os.path.join(sd, "B-写坏了.md")
            with open(p_broken, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ntype: source\n---# 标题\n")
            caught = False
            sys.stdout.flush()          # 让下面 stderr 的告警落在夹具判定之后，输出不串行
            try:
                verify_written([p_src, p_broken])
            except SystemExit as e:
                caught = (e.code or 0) != 0
            print(f"  [{'ok' if caught else 'FAIL'}] 反例 写后复算抓出 frontmatter 丢失"
                  f"（并置非零退出）")
            ok = ok and caught
    except Exception as e:                                        # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False

    # 🔴 守卫：自检未改动仓库内任何落点
    diff = _guard_diff(guard, _guard_state(
        wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),)))
    print(f"  [{'ok' if not diff else 'FAIL'}] 🔴 守卫：自检未改动仓库内任何落点"
          f"（{len(diff)} 处变化）")
    if diff:
        for d in diff[:10]:
            print("       ", d)
    ok = ok and not diff

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="把失效的 raw/pdf 回链改写到实际文件（按 DOI 配对）")
    ap.add_argument("--apply", action="store_true", help="写盘（默认干跑）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    # 🔴 `save_cache=a.apply`：干跑不落缓存（旧实现无条件 cache.save()）。
    mapping, total, unresolved, _cache = build_map(save_cache=a.apply)
    by_method = {}
    for tgt, (p, how) in mapping.items():
        by_method[how] = by_method.get(how, 0) + 1
    print(f"\n断链总命中 {total} 条 ｜ 可安全改写 {len(mapping)} 条 ｜ "
          f"匹配不上 {len(unresolved)} 条")
    print(f"配对方法分布: {by_method}")

    changed_files = 0
    written = 0
    targets = []                       # 待写页（干跑只打印、apply 才落盘）
    for f in sorted(glob.glob('wiki/sources/*.md')):
        t = read_text(f)
        fm_text, body = split_frontmatter(t)
        # ⚠️ 判据修正：`split_frontmatter` 无 frontmatter 时返回 `("", text)`，
        #    **永远不是 None**。旧写法 `if fm_text is None` 是死条件，
        #    等于这道闸门从来没关上过。
        if not fm_text.strip():
            continue
        new_fm = fm_text
        n = 0
        for tgt in sorted(mapping, key=len, reverse=True):
            if tgt not in new_fm:
                continue
            repl = mapping[tgt][0].replace(os.sep, '/')
            # 用完整链接匹配（含别名），只换目标，保留别名
            pat = re.compile(r'\[\[' + re.escape(tgt) + r'((?:\\?\|[^\]\n]*)?)\]\]')

            def _sub(m):
                return '[[' + repl + m.group(1) + ']]'
            new_fm, k = pat.subn(_sub, new_fm)
            n += k
        if n == 0:
            continue
        changed_files += 1
        written += n
        if a.apply:
            targets.append((f, new_fm, body, n))
        else:
            print(f"  待改 {os.path.basename(f)[:-3][:55]} : {n} 条")

    if a.apply:
        # —— 铁律 3：批量写盘前先备份、写后复算总量 ——
        saved = backup_files([x[0] for x in targets])
        if targets and not saved:
            print("❌ 备份失败，拒绝写盘", file=sys.stderr)
            return 2
        print("备份 %d 个待改文件 -> %s" % (len(saved), backup_dir()))
        done = []
        for f, new_fm2, body2, n in targets:
            new_text = join_frontmatter(new_fm2, body2)
            # 写前复核：必须仍能被同一解析器读出
            chk, _ = split_frontmatter(new_text)
            if not chk.strip():
                print("  [skip] 复核失败（未写盘）:", os.path.basename(f))
                continue
            write_keep_eol(f, new_text)
            done.append(f)
        verify_written(done)

    print(f"\n{'APPLIED' if a.apply else 'DRY-RUN'}: 涉及 {changed_files} 页 / {written} 条链接")
    if unresolved:
        print("\n⚠️ 匹配不上、保持原样（需人工或该 PDF 确已不在库内）:")
        for u in unresolved:
            print("   ", u)
    if not a.apply and written:
        print("\n加 --apply 执行写盘")
    return 0


if __name__ == "__main__":
    sys.exit(main())
